class Chan:
    cap: int
    items: list[int]

def offer(ch: Chan, v: int) -> tuple[Chan, bool]:
    """Return the channel with v appended if there is room, and True; otherwise return ch unchanged and False. Never blocks."""
    pre ch.items.len() <= ch.cap
    post out[1] == (ch.items.len() < ch.cap) and out[0].items.len() <= out[0].cap
    ex offer(Chan(cap=1, items=[]), 1) == (Chan(cap=1, items=[1]), True)
    ex offer(Chan(cap=1, items=[5]), 2) == (Chan(cap=1, items=[5]), False)
    if ch.items.len() < ch.cap:
        new_items = ch.items.copy()
        new_items.append(v)
        return (Chan(cap=ch.cap, items=new_items), True)
    return (Chan(cap=ch.cap, items=ch.items.copy()), False)

def accepted(cap: int, xs: list[int]) -> int uses nondet:
    """Count the sends accepted into a channel of capacity cap, trying each element of xs in order without blocking, and stop at the first send that finds the channel full. Examples: with cap 2 and xs [1, 2, 3] the result is 2; with cap 0 and xs [1] it is 0; with cap 5 and xs [] it is 0."""
    pre cap >= 0
    post out >= 0 and out <= cap and out <= xs.len()
    ch = Chan(cap=cap, items=[])
    n = 0
    for v in xs:
        ch, ok = offer(ch, v)
        if not ok:
            break
        n += 1
    return n
